<template><ion-page><ion-header class="ion-no-border"><ion-toolbar><ion-buttons slot="start"><ion-back-button default-href="/app/goats" /></ion-buttons><ion-title>Goat profile</ion-title></ion-toolbar></ion-header><ion-content><main class="page-wrap">
  <StatePanel v-if="loading" loading title="Loading profile" message="Retrieving goat details." /><StatePanel v-else-if="error" tone="danger" title="Unable to load goat" :message="error" :retry="load" />
  <template v-else-if="goat"><section class="profile-hero"><AuthImage :src="goat.cover_image_url" :alt="goat.name || goat.goat_id" /><div><span class="goat-id">{{ goat.goat_id }}</span><h1>{{ goat.name || 'Unnamed goat' }}</h1><p>{{ goat.breed_display }} · {{ goat.gender_display }}</p><span class="status-pill" :class="goat.status">{{ titleCase(goat.status) }}</span></div></section>
  <section class="profile-grid"><div><small>Age</small><strong>{{ goat.age }}</strong></div><div><small>Latest weight</small><strong>{{ goat.latest_weight?.weight_kg || goat.weight_kg || '—' }} kg</strong></div><div><small>Health</small><strong>{{ titleCase(goat.health_status) }}</strong></div><div><small>Last detected</small><strong>{{ relativeTime(goat.last_seen) }}</strong></div></section>
  <section class="section-block"><p class="eyebrow">IDENTIFICATION</p><dl class="detail-list"><div><dt>Tag number</dt><dd>{{ goat.tag_number || 'Not set' }}</dd></div><div><dt>Color & markings</dt><dd>{{ goat.color_markings || 'Not recorded' }}</dd></div><div><dt>Vaccination</dt><dd>{{ goat.vaccination_status_display }}</dd></div></dl></section>
  <section class="section-block"><p class="eyebrow">WEIGHT HISTORY</p><div v-if="goat.weight_history.length" class="weight-list"><div v-for="item in goat.weight_history.slice(0, 8)" :key="item.id"><strong>{{ item.weight_kg }} kg</strong><span>{{ new Date(item.measured_at).toLocaleString() }}</span><small>{{ item.source_display }}</small></div></div><p v-else class="empty-copy">No confirmed weight measurements yet.</p></section>
  </template></main></ion-content></ion-page></template>
<script setup lang="ts">
import { onMounted, ref } from 'vue'; import { useRoute } from 'vue-router'; import { IonBackButton, IonButtons, IonContent, IonHeader, IonPage, IonTitle, IonToolbar } from '@ionic/vue'; import AuthImage from '@/components/AuthImage.vue'; import StatePanel from '@/components/StatePanel.vue'; import { goatService } from '@/services/goat.service'; import type { GoatDetail } from '@/types/api'; import { relativeTime, titleCase } from '@/utils/format';
const route = useRoute(); const goat = ref<GoatDetail>(); const loading = ref(true); const error = ref(''); async function load() { loading.value = true; error.value = ''; try { goat.value = await goatService.detail(String(route.params.goatId)); } catch (reason) { error.value = reason instanceof Error ? reason.message : 'Unable to load profile.'; } finally { loading.value = false; } } onMounted(load);
</script>
